if hashlib.sha256(_recovery_raw).hexdigest()!=RECOVERY_SHA:
    raise RuntimeError('Embedded recovery helper hash mismatch')
R=types.ModuleType('_pinned_saved45');R.__file__='<pinned-saved45-helper>'
sys.modules[R.__name__]=R
exec(compile(_recovery_raw,R.__file__,'exec'),R.__dict__)
P=R.P
