def configure():
    P.ROOT=ROOT;P.UNIT=UNIT;P.COMPLETE=COMPLETE;P.VERSION='continuation-'+VERSION

@contextlib.contextmanager
def parent_root(path):
    old=P.ROOT;P.ROOT=path
    try:yield
    finally:P.ROOT=old

@contextlib.contextmanager
def io_lock():
    import fcntl
    fd=os.open(IO_LOCK,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    with os.fdopen(fd,'a') as f:
        fcntl.flock(f,fcntl.LOCK_EX)
        yield

def put_once(path,raw):
    if path.exists():need(read(path)==raw,'Existing immutable record differs: '+str(path))
    else:save(path,raw)

def seal_table(raw):
    tab={}
    for line in raw.decode().splitlines():
        h,sep,n=line.partition('  ');rel(n)
        need(sep and P.HEX.fullmatch(h) and n not in tab,'Invalid seal')
        tab[n]=h
    return tab

def verify_sealed(root,receipt,full=False):
    rr=parse(read(root/receipt));raw=read(root/'SHA256SUMS')
    need(sha(raw)==rr['seal_sha256'],'Seal pin mismatch: '+str(root))
    tab=seal_table(raw)
    if 'summary_sha256' in rr:need(hfile(root/'summary.json')==rr['summary_sha256'],'Summary hash mismatch')
    if full:
        for n,h in tab.items():need(hfile(root/rel(n))==h,'Sealed artifact changed: '+n)
    return rr,tab

def no_foreign_jobs():
    for u in (R.SOURCE_UNIT,R.UNIT):
        need(R.state(u)['ActiveState'] not in LIVE,'Old experiment still running: '+u)
    for p in Path('/proc').iterdir():
        if not p.name.isdigit():continue
        try:n=(p/'comm').read_text().strip()
        except (FileNotFoundError,ProcessLookupError):continue
        need(n not in ('llama-server','ollama'),'Unrelated inference process active; not stopping it')

def ordered_batches(rows):
    need(len(rows)==900 and len({r['id'] for r in rows})==900,'Expected 900 unique slots')
    need({r['id'] for r in rows}==P.grid(),'Wrong original grid')
    out=[]
    for i in range(0,900,5):
        block=rows[i:i+5]
        need(len({(r['task'],r['size'],r['form']) for r in block})==1,'Original group broken')
        need({r['condition'] for r in block}==set(P.ARMS),'Five-arm group incomplete')
        remaining=[r for j,r in enumerate(block,i) if j>=46]
        if remaining:out.append(dict(batch=f'group-{i//5:03d}',order_start=i,rows=remaining))
    need(len(out)==171 and len(out[0]['rows'])==4 and sum(len(b['rows']) for b in out)==854,'Continuation coverage mismatch')
    return out

