def archive_paths(dest,entries):
    """Build a streaming archive from explicitly selected files; never extract it."""
    checked(dest);part=dest.with_name(dest.name+'.partial')
    need(not dest.exists() and not part.exists(),'Archive exists; not overwriting')
    table={n:hfile(p) for n,p in sorted(entries.items())}
    need('SHA256SUMS' not in table,'Reserved archive name')
    raw=''.join(h+'  '+rel(n)+'\n' for n,h in table.items()).encode()
    size=sum(p.stat().st_size for p in entries.values())
    need(shutil.disk_usage(dest.parent).free>=size+P.GIB,'Insufficient archive disk')
    with part.open('xb') as sink:
        with tarfile.open(fileobj=sink,mode='w:gz',compresslevel=1) as tf:
            for n,p in sorted(entries.items()):
                t=tarfile.TarInfo(rel(n));t.size=p.stat().st_size;t.mode=0o600;t.mtime=0
                with P.regular(p) as f:tf.addfile(t,f)
            t=tarfile.TarInfo('SHA256SUMS');t.size=len(raw);t.mode=0o600;tf.addfile(t,io.BytesIO(raw))
        sink.flush();os.fsync(sink.fileno())
    pin=hfile(part);sz=part.stat().st_size;P.verify_archive(part,pin,sz)
    os.rename(part,dest)
    return dict(path=str(dest),sha256=pin,bytes=sz,files=len(table)+1,payload_readback_verified=True)

def audit_history():
    need(hfile(HISTORY/'control/runner.py')==RECOVERY_SHA,'Saved45 evaluator source changed')
    rr,tab=verify_sealed(HISTORY,'completion-receipt.json')
    need(rr['completion']==R.COMPLETE,'Saved45 evaluation not complete')
    wanted=('summary.json','source-audit.json','performance/outcomes.jsonl','validation/result-index.json')
    for n in wanted:need(hfile(HISTORY/n)==tab.get(n),'Historical result changed: '+n)
    hist=parse(read(HISTORY/'summary.json'))
    need(hist['source_generation_attempts']==46 and hist['not_attempted_slots']==854 and hist['source_saved_outputs']==45,'Unexpected historical coverage')
    need(hist['performance']['measurement_pending']==0 and hist['performance']['measurement_terminal']==33,'Historical timings incomplete')
    oldroot=R.ROOT
    try:
        R.ROOT=HISTORY;R.verify_snapshot()
    finally:R.ROOT=oldroot
    audit,table=R.audit_source(ORIGINAL)
    need(parse(read(HISTORY/'source-audit.json'))==audit,'Historical source replay differs')
    outcomes=[parse(x) for x in read(HISTORY/'performance/outcomes.jsonl').splitlines()]
    vr=parse(read(HISTORY/'validation/result-index.json'))
    ids=[r['id'] for r in audit['rows']]
    need([r['id'] for r in outcomes]==ids==[r['id'] for r in vr],'Historical result ordering differs')
    need(sum(r['measurement_valid'] is True for r in outcomes)==33,'Historical valid count differs')
    return audit,table,rr,outcomes,vr

def prepare():
    configure();P.host_basic()
    if ROOT.exists():
        need((ROOT/'ready.json').is_file(),'Partial preparation retained; not overwriting')
        verify_seed();return
    with P.locks():
        no_foreign_jobs();audit,table,hr,ho,hv=audit_history()
        with parent_root(ORIGINAL):
            core,c,e,f,m=P.modules();c.host_check(check_processes=False);e.no_other_jobs()
            assets=P.verify_assets()
        need(shutil.disk_usage('/root').free>=20*P.GIB,'Need 20GiB free to continue; no old results deleted')
        rows=parse(read(ORIGINAL/'inputs/rows.json'));batches=ordered_batches(rows)
        ROOT.mkdir(mode=0o700);manifest={}
        def cp(origin,n):
            b=read(origin);save(ROOT/n,b);os.chmod(ROOT/n,0o444)
            manifest[n]=dict(sha256=sha(b),bytes=len(b),source_path=str(origin))
        for n in table:cp(ORIGINAL/'inputs'/n,'inputs/'+n)
        for n in ('inputs/snapshot-manifest.json','input-receipt.json','native-input-receipt.json'):
            cp(ORIGINAL/n,n)
        for path in sorted((ORIGINAL/'native-inputs').glob('*.json')):cp(path,'native-inputs/'+path.name)
        for path in sorted((ORIGINAL/'acquisition').rglob('*')):
            checked(path)
            if path.is_file():cp(path,path.relative_to(ORIGINAL).as_posix())
        for n in ('summary.json','source-audit.json','performance/outcomes.jsonl','validation/result-index.json',
                  'completion-receipt.json','SHA256SUMS','checkpoint-receipt.json'):
            cp(HISTORY/n,'historical/'+n)
        for n in table:
            if n.startswith(('references/','package/','policy/')):
                cp(ROOT/'inputs'/n,'evaluation/'+n)
        jw(ROOT/'amendment.json',policy());jw(ROOT/'batch-plan.json',batches)
        for n in ('amendment.json','batch-plan.json'):
            manifest[n]=dict(sha256=hfile(ROOT/n),bytes=(ROOT/n).stat().st_size,source_path=None)
        jw(ROOT/'seed-manifest.json',manifest)
        runner=ROOT/'control/runner.py';save(runner,read(__file__))
        ready=dict(seed_sha256=hfile(ROOT/'seed-manifest.json'),runner_sha256=hfile(runner),
            historical_receipt_sha256=sha(canon(hr)),new_generation_requests_planned=854,utc=now())
        jw(ROOT/'ready.json',ready)
        verify_seed();verify_cached_assets()
        paths={n:ROOT/n for n in manifest}
        paths.update({'seed-manifest.json':ROOT/'seed-manifest.json','ready.json':ROOT/'ready.json','control/runner.py':runner})
        ar=archive_paths(ROOT/'bootstrap.tar.gz',paths)
        jw(ROOT/'bootstrap-receipt.json',dict(archive=ar,label='bootstrap',utc=now(),completed_900=False))
        print('CONTINUATION_PREPARED: retain 45 saved + 1 timeout; exactly 854 untouched slots; 171 groups',flush=True)

def verify_seed():
    rr=parse(read(ROOT/'ready.json'));raw=read(ROOT/'seed-manifest.json')
    need(sha(raw)==rr['seed_sha256'] and hfile(ROOT/'control/runner.py')==rr['runner_sha256'],'Continuation inputs/runner changed')
    for n,d in parse(raw).items():
        b=read(ROOT/rel(n));need(sha(b)==d['sha256'] and len(b)==d['bytes'],'Frozen seed changed: '+n)
    need(parse(read(ROOT/'amendment.json'))==policy(),'Execution policy changed')
    P.verify_inputs()

def verify_cached_assets():
    with parent_root(ROOT):rec=P.verify_assets()
    need(rec['model_sha256']=='ac9bc7a69dab38da1c790838955f1293420b55ab555ef6b4615efa1c1507b1ed','Not original downloaded GGUF')
    need(rec['model_bytes']==8988110784,'Wrong model size')
    archive=P.ASSETS/P.LLAMA_ASSET
    need(hfile(archive)==P.LLAMA_ARCHIVE_SHA and archive.stat().st_size==P.LLAMA_ARCHIVE_BYTES,'Pinned runtime archive changed')
    def inv(root):
        out={}
        for p in sorted(root.rglob('*')):
            n=p.relative_to(root).as_posix()
            if p.is_symlink():
                need(p.resolve().is_relative_to(root.resolve()),'Runtime symlink escapes');out[n]=['link',os.readlink(p)]
            elif p.is_file():out[n]=['file',hfile(p)]
            elif p.is_dir():out[n]=['dir']
            else:raise Blocked('Unexpected runtime entry')
        return out
    with tempfile.TemporaryDirectory(prefix='open14b-check-',dir=ROOT) as td:
        new=Path(td)/'runtime';P.extract_runtime(archive,new)
        need(inv(new)==inv(P.ASSETS/'runtime'),'Runtime differs from original pinned archive')
    print('CACHED_MODEL_AND_RUNTIME_VERIFIED; no downloads',flush=True)
    return rec

