def self_test():
    import types
    def sample_rows():
        first=[('bicg','MEDIUM','IR'),('cholesky','MEDIUM','IR'),('gemver','MEDIUM','C'),
            ('seidel-2d','MEDIUM','IR'),('gesummv','SMALL','C'),('3mm','MINI','C'),
            ('floyd-warshall','SMALL','C'),('cholesky','SMALL','C'),('fdtd-2d','MINI','C'),('heat-3d','MEDIUM','IR')]
        groups=first+sorted({(k,z,f) for k in P.KERNELS for z in P.SIZES for f in P.FORMS}-set(first))
        out=[]
        for key in groups:
            arms=['W2','P0','S1','S2','W1'] if key==first[-1] else list(P.ARMS)
            for arm in arms:out.append(P.identity('q27__'+'__'.join((*key,arm,'s0'))))
        return out
    class DummyModel:
        def __init__(self):self.events=[]
        def start(self):self.events.append('start')
        def stop(self):self.events.append('stop')
        def verify_native(self,row,doc):self.events.append('verify_native')
