def main():
    sys.dont_write_bytecode=True
    parser=argparse.ArgumentParser(description=__doc__);group=parser.add_mutually_exclusive_group(required=True)
    for name in ('self-test','run','watch','status','collect','stop','_prepare','_start','_worker','_status'):
        group.add_argument('--'+name,action='store_true',help=argparse.SUPPRESS if name.startswith('_') else None)
    group.add_argument('--_send',metavar='LABEL',help=argparse.SUPPRESS)
    group.add_argument('--_stream',nargs=2,metavar=('BATCH','ID'),help=argparse.SUPPRESS)
    a=parser.parse_args()
    if a.self_test:self_test();return
    os.umask(0o077);configure()
    if a._prepare:prepare();return
    if a._start:start();return
    if a._status:print(json.dumps(status(),ensure_ascii=False));return
    if a._send:send_archive(a._send);return
    if a._stream:stream_child(a._stream[1],a._stream[0]);return
    if a._worker:
        def sigterm(sig,frame):raise Blocked('User/system interruption; preserve partial work; no automatic numeric retry')
        signal.signal(signal.SIGTERM,sigterm)
        try:run_worker()
        except BaseException as exc:
            atomic(ROOT/'failure.json',dict(error=type(exc).__name__+': '+str(exc),traceback=traceback.format_exc(),utc=now(),automatic_retry=False))
            P.update(phase='BLOCKED',error=str(exc));raise
        return
    mode=next(n for n in ('run','watch','status','collect','stop') if getattr(a,n));local(mode)

if __name__=='__main__':
    try:main()
    except KeyboardInterrupt:raise SystemExit(130)
    except Exception as exc:
        print('CONTINUATION_BLOCKED: '+type(exc).__name__+': '+str(exc),file=sys.stderr,flush=True)
        print('Existing data preserved; no candidate automatically regenerated or remeasured.',file=sys.stderr)
        raise SystemExit(2)
